package com.crazy4lamb.crmbi.controller;
import static com.crazy4lamb.crmbi.controller.AuthController.user;import static com.crazy4lamb.crmbi.core.Api.ok;
import com.crazy4lamb.crmbi.core.*;import com.crazy4lamb.crmbi.service.AclService;import com.crazy4lamb.crmbi.service.MetricService;import jakarta.servlet.http.HttpServletRequest;import java.time.LocalDate;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/metric") public class MetricController{
 private final Db db;private final AclService acl;private final MetricService metrics;public MetricController(Db db,AclService acl,MetricService metrics){this.db=db;this.acl=acl;this.metrics=metrics;}
 @GetMapping("/meta")public Map<String,Object>meta(HttpServletRequest r){return db.tx(user(r),x->ok(Map.of("reports",reports(),"aggs",pairs("sum","求和","count","计数","count_distinct","去重计数","avg","平均","max","最大","min","最小"),"dateModes",List.of(List.of("day","当日"),List.of("mtd","本月累计"),List.of("month","整月"),List.of("last7","近 7 天"),List.of("last30","近 30 天"),List.of("all","全部")),"units",List.of("元","份","笔","家","条","个","台","%","天"),"directions",List.of(List.of("up","越大越好"),List.of("down","越小越好")),"ops",pairs("eq","等于","ne","不等于","gt","大于","ge","大于等于","lt","小于","le","小于等于","like","包含","isnull","为空","notnull","不为空"))));}
 @GetMapping("/list")public Map<String,Object>list(HttpServletRequest r){return db.tx(user(r),x->ok(db.many("select m.*,r.name report_name,r.code report_code,v.stat_date last_date,v.value last_value from bi_metric m left join rpt_report r on r.id=m.report_id left join lateral(select stat_date,value from bi_metric_value where metric_id=m.id order by stat_date desc limit 1)v on true order by m.metric_group,m.id")));}
 @GetMapping("/{id}")public Map<String,Object>one(@PathVariable int id,HttpServletRequest r){return db.tx(user(r),x->{Map<String,Object>m=db.one("select * from bi_metric where id=:id",Map.of("id",id));if(m==null)throw ApiException.notFound("指标不存在");return ok(m);});}
 @GetMapping("/{id}/values")public Map<String,Object>values(@PathVariable int id,@RequestParam(required=false)String from,@RequestParam(required=false)String to,HttpServletRequest r){return db.tx(user(r),x->{String start=from==null?LocalDate.now().minusDays(90).toString():from,end=to==null?LocalDate.now().toString():to;List<Map<String,Object>>rows=db.many("select stat_date,value,prev_value,calc_time from bi_metric_value where metric_id=:id and stat_date between cast(:from as date) and cast(:to as date) order by stat_date",Map.of("id",id,"from",start,"to",end));List<Map<String,Object>>vals=rows.stream().map(v->{Map<String,Object>m=new LinkedHashMap<>();m.put("statDate",v.get("stat_date"));m.put("value",v.get("value"));m.put("prevValue",v.get("prev_value"));m.put("calcTime",v.get("calc_time"));return m;}).toList();double sum=vals.stream().map(v->v.get("value")).filter(Number.class::isInstance).mapToDouble(v->((Number)v).doubleValue()).sum();DoubleSummaryStatistics s=vals.stream().map(v->v.get("value")).filter(Number.class::isInstance).mapToDouble(v->((Number)v).doubleValue()).summaryStatistics();Map<String,Object>summary=new LinkedHashMap<>();summary.put("count",vals.size());summary.put("lastDate",vals.isEmpty()?null:vals.getLast().get("statDate"));summary.put("lastValue",vals.isEmpty()?null:vals.getLast().get("value"));summary.put("sum",sum);summary.put("avg",vals.isEmpty()?0:s.getAverage());summary.put("max",vals.isEmpty()?null:s.getMax());summary.put("min",vals.isEmpty()?null:s.getMin());return ok(Map.of("metric",db.one("select * from bi_metric where id=:id",Map.of("id",id)),"from",start,"to",end,"values",vals,"summary",summary));});}
 @PostMapping("/{id}/preview")public Map<String,Object>preview(@PathVariable int id,@RequestBody(required=false)Map<String,Object>b,HttpServletRequest r){return db.tx(user(r),x->{LocalDate date=b!=null&&b.get("statDate")!=null?LocalDate.parse(String.valueOf(b.get("statDate"))):LocalDate.now().minusDays(1);Map<String,Object>metric=db.one("select * from bi_metric where id=:id",Map.of("id",id));if(metric==null)throw ApiException.notFound("指标不存在");return ok(Map.of("statDate",date,"value",metrics.compute(metric,date),"range",Map.of("from",date,"to",date)));});}
 @PostMapping("/{id}/compute")public Map<String,Object>compute(@PathVariable int id,@RequestBody(required=false)Map<String,Object>b,HttpServletRequest r){design(user(r));return db.tx(user(r),x->{LocalDate from=b!=null&&b.get("from")!=null?LocalDate.parse(String.valueOf(b.get("from"))):b!=null&&b.get("statDate")!=null?LocalDate.parse(String.valueOf(b.get("statDate"))):LocalDate.now().minusDays(1),to=b!=null&&b.get("to")!=null?LocalDate.parse(String.valueOf(b.get("to"))):from;if(to.isBefore(from)||to.isAfter(from.plusDays(366)))throw ApiException.bad("补算日期范围无效或超过 366 天");Map<String,Object>metric=db.one("select * from bi_metric where id=:id",Map.of("id",id));if(metric==null)throw ApiException.notFound("指标不存在");int rows=0;for(LocalDate date=from;!date.isAfter(to);date=date.plusDays(1)){metrics.persist(metric,date,null);rows++;}return ok(Map.of("rows",rows),"已计算 "+rows+" 条");});}
 @PostMapping public Map<String,Object>create(@RequestBody Map<String,Object>b,HttpServletRequest r){design(user(r));required(b);return db.tx(user(r),x->{String code=String.valueOf(b.getOrDefault("code","m_"+Long.toString(System.currentTimeMillis(),36)));Map<String,Object>p=metricParams(b);p.put("code",code);p.put("owner",user(r).id());Number id=db.insertId("insert into bi_metric(code,name,metric_group,report_id,measure_key,agg_fn,date_field_key,date_mode,filters,unit,precision,direction,description,owner_id,status) values(:code,:name,:grp,:report,:measure,:agg,:dateField,:mode,cast(:filters as jsonb),:unit,:precision,:direction,:description,:owner,:status)",p);return ok(Map.of("id",id,"code",code),"指标已创建");});}
 @PutMapping("/{id}")public Map<String,Object>update(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest r){design(user(r));required(b);return db.tx(user(r),x->{Map<String,Object>p=metricParams(b);p.put("id",id);int n=db.update("update bi_metric set name=:name,metric_group=:grp,report_id=:report,measure_key=:measure,agg_fn=:agg,date_field_key=:dateField,date_mode=:mode,filters=cast(:filters as jsonb),unit=:unit,precision=:precision,direction=:direction,description=:description,status=:status,updated_at=now() where id=:id",p);if(n==0)throw ApiException.notFound("指标不存在");return ok(null,"已保存");});}
 @DeleteMapping("/{id}")public Map<String,Object>delete(@PathVariable int id,HttpServletRequest r){design(user(r));return db.tx(user(r),x->{db.update("delete from bi_metric where id=:id",Map.of("id",id));return ok(null,"已删除");});}
 private List<Map<String,Object>>reports(){List<Map<String,Object>>rs=db.many("select r.id,r.code,r.name,r.category,d.name dataset_name from rpt_report r join rpt_dataset d on d.id=r.dataset_id order by r.category,r.id"),fs=db.many("select report_id,field_key,field_name,field_type,field_role,agg_fn,is_custom from rpt_report_field order by report_id,sort_no,id");rs.forEach(r->r.put("fields",fs.stream().filter(f->Objects.equals(r.get("id"),f.get("report_id"))).toList()));return rs;}
 private static void required(Map<String,Object>b){if(b.get("name")==null||b.get("reportId")==null||b.get("measureKey")==null||b.get("dateFieldKey")==null)throw ApiException.bad("指标名称、数据来源、度量字段与日期字段必填");}
 private static Map<String,Object>metricParams(Map<String,Object>b){Map<String,Object>p=new LinkedHashMap<>();p.put("name",b.get("name"));p.put("grp",b.getOrDefault("metricGroup","自定义"));p.put("report",b.get("reportId"));p.put("measure",b.get("measureKey"));p.put("agg",b.getOrDefault("aggFn","sum"));p.put("dateField",b.get("dateFieldKey"));p.put("mode",b.getOrDefault("dateMode","day"));p.put("filters",json(b.getOrDefault("filters",List.of())));p.put("unit",b.get("unit"));p.put("precision",b.getOrDefault("precision",0));p.put("direction",b.getOrDefault("direction","up"));p.put("description",b.get("description"));p.put("status",b.getOrDefault("status","1"));return p;}
 private static String json(Object value){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value);}catch(Exception e){throw ApiException.bad("过滤条件格式无效");}}
 private void design(UserPrincipal u){acl.require(u,"action","metric:design","无权限：需要「指标设计」权限");}private static List<Map<String,Object>>pairs(String...v){List<Map<String,Object>>o=new ArrayList<>();for(int i=0;i<v.length;i+=2)o.add(Map.of("value",v[i],"label",v[i+1]));return o;}private static Map<String,Object>params(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put(String.valueOf(v[i]),v[i+1]);return m;}
}
